func (mmUpdateAggregate *mAggregateServiceMockUpdateAggregate) invocationsDone() bool {
	if len(mmUpdateAggregate.expectations) == 0 && mmUpdateAggregate.defaultExpectation == nil && mmUpdateAggregate.mock.funcUpdateAggregate == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmUpdateAggregate.mock.afterUpdateAggregateCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmUpdateAggregate.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// UpdateAggregate implements mm_handlers.AggregateService
func (mmUpdateAggregate *AggregateServiceMock) UpdateAggregate(ctx context.Context, id uint, updates map[string]any) (ap1 *entities.Aggregate, err error) {
	mm_atomic.AddUint64(&mmUpdateAggregate.beforeUpdateAggregateCounter, 1)
	defer mm_atomic.AddUint64(&mmUpdateAggregate.afterUpdateAggregateCounter, 1)

	mmUpdateAggregate.t.Helper()

	if mmUpdateAggregate.inspectFuncUpdateAggregate != nil {
		mmUpdateAggregate.inspectFuncUpdateAggregate(ctx, id, updates)
	}

	mm_params := AggregateServiceMockUpdateAggregateParams{ctx, id, updates}

	// Record call args
	mmUpdateAggregate.UpdateAggregateMock.mutex.Lock()
	mmUpdateAggregate.UpdateAggregateMock.callArgs = append(mmUpdateAggregate.UpdateAggregateMock.callArgs, &mm_params)
	mmUpdateAggregate.UpdateAggregateMock.mutex.Unlock()

	for _, e := range mmUpdateAggregate.UpdateAggregateMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.ap1, e.results.err
		}
	}

	if mmUpdateAggregate.UpdateAggregateMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmUpdateAggregate.UpdateAggregateMock.defaultExpectation.Counter, 1)
		mm_want := mmUpdateAggregate.UpdateAggregateMock.defaultExpectation.params
		mm_want_ptrs := mmUpdateAggregate.UpdateAggregateMock.defaultExpectation.paramPtrs

		mm_got := AggregateServiceMockUpdateAggregateParams{ctx, id, updates}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmUpdateAggregate.t.Errorf("AggregateServiceMock.UpdateAggregate got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdateAggregate.UpdateAggregateMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.id != nil && !minimock.Equal(*mm_want_ptrs.id, mm_got.id) {
				mmUpdateAggregate.t.Errorf("AggregateServiceMock.UpdateAggregate got unexpected parameter id, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdateAggregate.UpdateAggregateMock.defaultExpectation.expectationOrigins.originId, *mm_want_ptrs.id, mm_got.id, minimock.Diff(*mm_want_ptrs.id, mm_got.id))
			}

			if mm_want_ptrs.updates != nil && !minimock.Equal(*mm_want_ptrs.updates, mm_got.updates) {
				mmUpdateAggregate.t.Errorf("AggregateServiceMock.UpdateAggregate got unexpected parameter updates, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmUpdateAggregate.UpdateAggregateMock.defaultExpectation.expectationOrigins.originUpdates, *mm_want_ptrs.updates, mm_got.updates, minimock.Diff(*mm_want_ptrs.updates, mm_got.updates))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmUpdateAggregate.t.Errorf("AggregateServiceMock.UpdateAggregate got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmUpdateAggregate.UpdateAggregateMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmUpdateAggregate.UpdateAggregateMock.defaultExpectation.results
		if mm_results == nil {
			mmUpdateAggregate.t.Fatal("No results are set for the AggregateServiceMock.UpdateAggregate")
		}
		return (*mm_results).ap1, (*mm_results).err
	}
	if mmUpdateAggregate.funcUpdateAggregate != nil {
		return mmUpdateAggregate.funcUpdateAggregate(ctx, id, updates)
	}
	mmUpdateAggregate.t.Fatalf("Unexpected call to AggregateServiceMock.UpdateAggregate. %v %v %v", ctx, id, updates)
	return
}

