// MinimockUpdateAggregateDone returns true if the count of the UpdateAggregate invocations corresponds
// the number of defined expectations
func (m *AggregateServiceMock) MinimockUpdateAggregateDone() bool {
	if m.UpdateAggregateMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.UpdateAggregateMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.UpdateAggregateMock.invocationsDone()
}

// MinimockUpdateAggregateInspect logs each unmet expectation
func (m *AggregateServiceMock) MinimockUpdateAggregateInspect() {
	for _, e := range m.UpdateAggregateMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to AggregateServiceMock.UpdateAggregate at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterUpdateAggregateCounter := mm_atomic.LoadUint64(&m.afterUpdateAggregateCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.UpdateAggregateMock.defaultExpectation != nil && afterUpdateAggregateCounter < 1 {
		if m.UpdateAggregateMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to AggregateServiceMock.UpdateAggregate at\n%s", m.UpdateAggregateMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to AggregateServiceMock.UpdateAggregate at\n%s with params: %#v", m.UpdateAggregateMock.defaultExpectation.expectationOrigins.origin, *m.UpdateAggregateMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcUpdateAggregate != nil && afterUpdateAggregateCounter < 1 {
		m.t.Errorf("Expected call to AggregateServiceMock.UpdateAggregate at\n%s", m.funcUpdateAggregateOrigin)
	}

	if !m.UpdateAggregateMock.invocationsDone() && afterUpdateAggregateCounter > 0 {
		m.t.Errorf("Expected %d calls to AggregateServiceMock.UpdateAggregate at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.UpdateAggregateMock.expectedInvocations), m.UpdateAggregateMock.expectedInvocationsOrigin, afterUpdateAggregateCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *AggregateServiceMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockApplyAggregateToClassInspect()

			m.MinimockCreateAggregateInspect()

			m.MinimockDeleteAggregateInspect()

			m.MinimockGetAggregatesInspect()

			m.MinimockUpdateAggregateInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *AggregateServiceMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *AggregateServiceMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockApplyAggregateToClassDone() &&
		m.MinimockCreateAggregateDone() &&
		m.MinimockDeleteAggregateDone() &&
		m.MinimockGetAggregatesDone() &&
		m.MinimockUpdateAggregateDone()
}
